// MESH1 is little-endian. Its 48-byte preamble carries version and mesh counts, followed by
// 24-byte section descriptors {id, offset, byteLength, CRC32, recordCount, recordStride}.
// Sections begin on eight-byte boundaries so browser and Node loaders can expose typed views.
const MAGIC_BYTES = Uint8Array.of(0x4d, 0x45, 0x53, 0x48, 0x31, 0, 0, 0);
const PREAMBLE_BYTES = 48;
const SECTION_ENTRY_BYTES = 24;

export const MESH_ASSET_VERSION = 1;
export const NO_SLIT_COMPONENT = 0xffffffff;

export const MESH_SECTIONS = Object.freeze({
  positions: { id: 1, stride: 12, countFrom: 'vertexCount' },
  normals: { id: 2, stride: 12, countFrom: 'vertexCount' },
  uv0: { id: 3, stride: 8, countFrom: 'vertexCount' },
  indices: { id: 4, stride: 4, countFrom: 'indexCount' },
  triangleChartIds: { id: 5, stride: 4, countFrom: 'triangleCount' },
  charts: { id: 6, stride: 32, countFrom: 'chartCount' },
  seamPairs: { id: 7, stride: 56, countFrom: 'seamPairCount' },
  slitComponents: { id: 8, stride: 24, countFrom: 'slitComponentCount' },
});

const SECTION_NAMES_BY_ID = new Map(
  Object.entries(MESH_SECTIONS).map(([name, definition]) => [definition.id, name]),
);

export function parseMeshAsset(input, { verifyCrc = true } = {}) {
  const bytes = alignedByteView(input);
  requireCondition(bytes.byteLength >= PREAMBLE_BYTES, 'MESH1: truncated header');
  for (let index = 0; index < MAGIC_BYTES.length; index += 1) {
    requireCondition(bytes[index] === MAGIC_BYTES[index], 'MESH1: invalid magic');
  }
  const header = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  requireCondition(header.getUint32(8, true) === MESH_ASSET_VERSION, 'MESH1: unsupported version');
  const headerByteLength = header.getUint32(12, true);
  const sectionCount = header.getUint32(16, true);
  requireCondition(sectionCount === Object.keys(MESH_SECTIONS).length, 'MESH1: unexpected section count');
  requireCondition(
    headerByteLength === alignTo(PREAMBLE_BYTES + sectionCount * SECTION_ENTRY_BYTES, 8),
    'MESH1: invalid header length',
  );
  requireCondition(headerByteLength <= bytes.byteLength, 'MESH1: header overruns input');

  const counts = {
    vertexCount: header.getUint32(20, true),
    triangleCount: header.getUint32(24, true),
    chartCount: header.getUint32(28, true),
    seamPairCount: header.getUint32(32, true),
    directionalSideCount: header.getUint32(36, true),
    slitComponentCount: header.getUint32(40, true),
  };
  counts.indexCount = counts.triangleCount * 3;
  requireCondition(counts.directionalSideCount === counts.seamPairCount * 2, 'MESH1: side count mismatch');

  const sectionEntries = readSectionEntries(header, sectionCount, counts, headerByteLength, bytes.byteLength);
  const rawSections = {};
  for (const [name, entry] of Object.entries(sectionEntries)) {
    const sectionBytes = bytes.subarray(entry.byteOffset, entry.byteOffset + entry.byteLength);
    if (verifyCrc) {
      requireCondition(crc32(sectionBytes) === entry.crc32, `MESH1: CRC mismatch in ${name}`);
    }
    rawSections[name] = sectionBytes;
  }

  return {
    version: MESH_ASSET_VERSION,
    ...counts,
    positions: typedSection(Float32Array, rawSections.positions),
    normals: typedSection(Float32Array, rawSections.normals),
    uv0: typedSection(Float32Array, rawSections.uv0),
    indices: typedSection(Uint32Array, rawSections.indices),
    triangleChartIds: typedSection(Uint32Array, rawSections.triangleChartIds),
    charts: decodeCharts(rawSections.charts),
    seamPairs: decodeSeamPairs(rawSections.seamPairs),
    slitComponents: decodeSlitComponents(rawSections.slitComponents),
    rawSections,
    sectionEntries,
  };
}

export function crc32(bytes) {
  let value = 0xffffffff;
  for (const byte of bytes) value = CRC_TABLE[(value ^ byte) & 0xff] ^ (value >>> 8);
  return (value ^ 0xffffffff) >>> 0;
}

export function meshAssetHeaderLayout() {
  return {
    magicBytes: MAGIC_BYTES.slice(),
    preambleBytes: PREAMBLE_BYTES,
    sectionEntryBytes: SECTION_ENTRY_BYTES,
    headerBytes: alignTo(PREAMBLE_BYTES + Object.keys(MESH_SECTIONS).length * SECTION_ENTRY_BYTES, 8),
  };
}

function readSectionEntries(header, sectionCount, counts, headerByteLength, assetByteLength) {
  const entries = {};
  const ranges = [];
  for (let entryIndex = 0; entryIndex < sectionCount; entryIndex += 1) {
    const offset = PREAMBLE_BYTES + entryIndex * SECTION_ENTRY_BYTES;
    const id = header.getUint32(offset, true);
    const name = SECTION_NAMES_BY_ID.get(id);
    requireCondition(name && !entries[name], `MESH1: unknown or duplicate section ${id}`);
    const entry = {
      id,
      byteOffset: header.getUint32(offset + 4, true),
      byteLength: header.getUint32(offset + 8, true),
      crc32: header.getUint32(offset + 12, true),
      recordCount: header.getUint32(offset + 16, true),
      recordStride: header.getUint32(offset + 20, true),
    };
    const definition = MESH_SECTIONS[name];
    requireCondition(entry.recordStride === definition.stride, `MESH1: invalid ${name} stride`);
    requireCondition(entry.recordCount === counts[definition.countFrom], `MESH1: invalid ${name} count`);
    requireCondition(entry.byteLength === entry.recordCount * entry.recordStride, `MESH1: invalid ${name} length`);
    requireCondition(entry.byteOffset % 8 === 0, `MESH1: unaligned ${name} section`);
    requireCondition(entry.byteOffset >= headerByteLength, `MESH1: ${name} overlaps the header`);
    requireCondition(entry.byteOffset + entry.byteLength <= assetByteLength, `MESH1: ${name} overruns input`);
    entries[name] = entry;
    ranges.push([entry.byteOffset, entry.byteOffset + entry.byteLength, name]);
  }
  requireCondition(Object.keys(entries).length === Object.keys(MESH_SECTIONS).length, 'MESH1: missing section');
  ranges.sort((left, right) => left[0] - right[0]);
  for (let index = 1; index < ranges.length; index += 1) {
    requireCondition(ranges[index - 1][1] <= ranges[index][0], `MESH1: overlapping ${ranges[index][2]} section`);
  }
  return entries;
}

function decodeCharts(bytes) {
  const view = dataView(bytes);
  const records = [];
  for (let byteOffset = 0; byteOffset < bytes.byteLength; byteOffset += MESH_SECTIONS.charts.stride) {
    records.push({
      triangleCount: view.getUint32(byteOffset, true),
      uvBounds: [0, 1, 2, 3].map((index) => view.getFloat32(byteOffset + 8 + index * 4, true)),
      uvArea: view.getFloat64(byteOffset + 24, true),
    });
  }
  return records;
}

function decodeSeamPairs(bytes) {
  const view = dataView(bytes);
  const records = [];
  for (let byteOffset = 0; byteOffset < bytes.byteLength; byteOffset += MESH_SECTIONS.seamPairs.stride) {
    const side0 = {
      triangleIndex: view.getUint32(byteOffset, true),
      vertex0: view.getUint32(byteOffset + 8, true),
      vertex1: view.getUint32(byteOffset + 12, true),
      chartId: view.getUint32(byteOffset + 24, true),
      uvAltitude: view.getFloat32(byteOffset + 44, true),
    };
    const side1 = {
      triangleIndex: view.getUint32(byteOffset + 4, true),
      vertex0: view.getUint32(byteOffset + 16, true),
      vertex1: view.getUint32(byteOffset + 20, true),
      chartId: view.getUint32(byteOffset + 28, true),
      uvAltitude: view.getFloat32(byteOffset + 48, true),
    };
    records.push({
      sides: [side0, side1],
      slitComponentId: view.getUint32(byteOffset + 32, true),
      isSlit: Boolean(view.getUint32(byteOffset + 36, true) & 1),
      foldAngleRadians: view.getFloat32(byteOffset + 40, true),
      coincidenceError: view.getFloat32(byteOffset + 52, true),
    });
  }
  return records;
}

function decodeSlitComponents(bytes) {
  const view = dataView(bytes);
  const records = [];
  for (let byteOffset = 0; byteOffset < bytes.byteLength; byteOffset += MESH_SECTIONS.slitComponents.stride) {
    records.push({
      chartId: view.getUint32(byteOffset, true),
      edgeCount: view.getUint32(byteOffset + 4, true),
      maxBranchDegree: view.getUint32(byteOffset + 8, true),
      branchVertexCount: view.getUint32(byteOffset + 12, true),
      closedLoop: Boolean(view.getUint32(byteOffset + 16, true)),
    });
  }
  return records;
}

function typedSection(ArrayType, bytes) {
  return new ArrayType(bytes.buffer, bytes.byteOffset, bytes.byteLength / ArrayType.BYTES_PER_ELEMENT);
}

function dataView(bytes) {
  return new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
}

function alignedByteView(input) {
  requireCondition(ArrayBuffer.isView(input) || input instanceof ArrayBuffer, 'MESH1: expected binary input');
  const bytes = input instanceof ArrayBuffer
    ? new Uint8Array(input)
    : new Uint8Array(input.buffer, input.byteOffset, input.byteLength);
  return bytes.byteOffset % 8 === 0 ? bytes : bytes.slice();
}

function alignTo(value, alignment) {
  return Math.ceil(value / alignment) * alignment;
}

function requireCondition(condition, message) {
  if (!condition) throw new Error(message);
}

const CRC_TABLE = Uint32Array.from({ length: 256 }, (_, index) => {
  let value = index;
  for (let bit = 0; bit < 8; bit += 1) value = (value >>> 1) ^ ((value & 1) ? 0xedb88320 : 0);
  return value >>> 0;
});

import { fetchWgsl } from '../gpu/wgsl.js';
import { makeIcosaLightUniformData } from './light-rig.js';

const CLEAR_COLOUR = Object.freeze({ r: 0.004, g: 0.006, b: 0.005, a: 1 });
const TEST_TARGET_SIZE = 256;

export async function createFixtureMeshRenderer({
  device,
  registry,
  canvas,
  cameraRig,
  materialUniforms,
  mesh,
  displayChain,
  goldLut,
  dev = true,
  onCompilationMessage,
}) {
  const context = canvas.getContext('webgpu');
  const colourFormat = navigator.gpu.getPreferredCanvasFormat();
  context.configure({
    device,
    format: colourFormat,
    alphaMode: 'opaque',
    usage: GPUTextureUsage.RENDER_ATTACHMENT,
  });

  const lightBuffer = registry.createBuffer({
    label: 'look-icosa-light-uniforms',
    size: 32 * 16,
    usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
  });
  device.queue.writeBuffer(lightBuffer, 0, makeIcosaLightUniformData());

  const frameLayout = device.createBindGroupLayout({
    label: 'look-material-frame-layout',
    entries: [
      { binding: 0, visibility: GPUShaderStage.VERTEX | GPUShaderStage.FRAGMENT, buffer: { type: 'uniform' } },
      { binding: 1, visibility: GPUShaderStage.FRAGMENT, buffer: { type: 'uniform' } },
      { binding: 2, visibility: GPUShaderStage.FRAGMENT, buffer: { type: 'uniform' } },
    ],
  });
  const textureLayout = device.createBindGroupLayout({
    label: 'look-material-texture-layout',
    entries: [
      textureEntry(0, 'float'),
      samplerEntry(1),
      samplerEntry(2),
      textureEntry(3, 'unfilterable-float'),
      textureEntry(4, 'float'),
      samplerEntry(5),
    ],
  });
  const pipelineLayout = device.createPipelineLayout({
    label: 'look-material-pipeline-layout',
    bindGroupLayouts: [frameLayout, textureLayout],
  });
  const frameBindGroup = device.createBindGroup({
    label: 'look-material-frame-bind',
    layout: frameLayout,
    entries: [
      { binding: 0, resource: { buffer: cameraRig.uniformBuffer } },
      { binding: 1, resource: { buffer: materialUniforms.buffer } },
      { binding: 2, resource: { buffer: lightBuffer } },
    ],
  });
  const displayLinearSampler = device.createSampler({
    label: 'look-display-linear-sampler',
    addressModeU: 'clamp-to-edge',
    addressModeV: 'clamp-to-edge',
    magFilter: 'linear',
    minFilter: 'linear',
  });
  const displayNearestSampler = device.createSampler({
    label: 'look-display-nearest-sampler',
    addressModeU: 'clamp-to-edge',
    addressModeV: 'clamp-to-edge',
    magFilter: 'nearest',
    minFilter: 'nearest',
  });
  const goldSampler = device.createSampler({
    label: 'look-gold-response-sampler',
    addressModeU: 'clamp-to-edge',
    addressModeV: 'clamp-to-edge',
    magFilter: 'linear',
    minFilter: 'linear',
  });
  const textureBindGroups = displayChain.maximumViews.map((maximumView, index) => device.createBindGroup({
    label: `look-material-texture-bind-${index}`,
    layout: textureLayout,
    entries: [
      { binding: 0, resource: displayChain.sampleView },
      { binding: 1, resource: displayLinearSampler },
      { binding: 2, resource: displayNearestSampler },
      { binding: 3, resource: maximumView },
      { binding: 4, resource: goldLut.view },
      { binding: 5, resource: goldSampler },
    ],
  }));

  const [slimeSource, goldSource] = await Promise.all([
    fetchWgsl(new URL('./slime.wgsl', import.meta.url)),
    fetchWgsl(new URL('./gold.wgsl', import.meta.url)),
  ]);
  const slimeModule = await checkedModule(device, 'look-slime', slimeSource, dev, onCompilationMessage);
  const goldModule = await checkedModule(device, 'look-gold', goldSource, dev, onCompilationMessage);
  const vertexBuffers = [{
    arrayStride: 8 * 4,
    stepMode: 'vertex',
    attributes: [
      { shaderLocation: 0, offset: 0, format: 'float32x3' },
      { shaderLocation: 1, offset: 3 * 4, format: 'float32x3' },
      { shaderLocation: 2, offset: 6 * 4, format: 'float32x2' },
    ],
  }];
  const depthStencil = {
    format: 'depth24plus',
    depthWriteEnabled: true,
    depthCompare: 'less-equal',
  };
  const goldPipeline = await device.createRenderPipelineAsync({
    label: 'look-gold-pipeline',
    layout: pipelineLayout,
    vertex: { module: goldModule, entryPoint: 'goldVertex', buffers: vertexBuffers },
    fragment: { module: goldModule, entryPoint: 'goldFragment', targets: [{ format: colourFormat }] },
    primitive: { topology: 'triangle-list', cullMode: 'none' },
    depthStencil,
  });
  const slimePipeline = await device.createRenderPipelineAsync({
    label: 'look-slime-pipeline',
    layout: pipelineLayout,
    vertex: { module: slimeModule, entryPoint: 'slimeVertex', buffers: vertexBuffers },
    fragment: {
      module: slimeModule,
      entryPoint: 'slimeFragment',
      targets: [{
        format: colourFormat,
        blend: {
          color: { srcFactor: 'one', dstFactor: 'one-minus-src-alpha', operation: 'add' },
          alpha: { srcFactor: 'one', dstFactor: 'one-minus-src-alpha', operation: 'add' },
        },
      }],
    },
    primitive: { topology: 'triangle-list', cullMode: 'none' },
    depthStencil: { ...depthStencil, depthWriteEnabled: false },
  });

  const testColour = registry.createTexture({
    label: 'look-test-colour',
    size: [TEST_TARGET_SIZE, TEST_TARGET_SIZE],
    format: colourFormat,
    usage: GPUTextureUsage.RENDER_ATTACHMENT | GPUTextureUsage.COPY_SRC,
  });
  const testDepth = makeDepthTexture(registry, 'look-test-depth', TEST_TARGET_SIZE, TEST_TARGET_SIZE);
  const testColourView = testColour.createView();
  const testDepthView = testDepth.createView();
  const testBytesPerRow = align(TEST_TARGET_SIZE * 4, 256);
  const testReadback = registry.createBuffer({
    label: 'look-test-colour-readback',
    size: testBytesPerRow * TEST_TARGET_SIZE,
    usage: GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ,
  });

  let canvasDepth = null;
  let canvasDepthView = null;
  let canvasWidth = 0;
  let canvasHeight = 0;

  function encodeCanvas(encoder, params) {
    resizeCanvasTarget();
    cameraRig.update(canvasWidth, canvasHeight);
    encodeMeshPass(
      encoder,
      context.getCurrentTexture().createView(),
      canvasDepthView,
      params,
      'look-canvas-mesh-pass',
    );
  }

  function encodeTestFrame(encoder, params) {
    cameraRig.update(TEST_TARGET_SIZE, TEST_TARGET_SIZE);
    encodeMeshPass(encoder, testColourView, testDepthView, params, 'look-offscreen-mesh-pass');
    encoder.copyTextureToBuffer(
      { texture: testColour },
      { buffer: testReadback, bytesPerRow: testBytesPerRow, rowsPerImage: TEST_TARGET_SIZE },
      [TEST_TARGET_SIZE, TEST_TARGET_SIZE, 1],
    );
  }

  function encodeMeshPass(encoder, colourView, depthView, params, label) {
    const pass = encoder.beginRenderPass({
      label,
      colorAttachments: [{
        view: colourView,
        clearValue: CLEAR_COLOUR,
        loadOp: 'clear',
        storeOp: 'store',
      }],
      depthStencilAttachment: {
        view: depthView,
        depthClearValue: 1,
        depthLoadOp: 'clear',
        depthStoreOp: 'store',
      },
    });
    pass.setVertexBuffer(0, mesh.vertexBuffer);
    pass.setIndexBuffer(mesh.indexBuffer, mesh.indexFormat);
    pass.setBindGroup(0, frameBindGroup);
    pass.setBindGroup(1, textureBindGroups[displayChain.currentMaximumIndex()]);
    if (params.useGoldWaferBody) {
      pass.setPipeline(goldPipeline);
      pass.drawIndexed(mesh.indexCount);
    }
    pass.setPipeline(slimePipeline);
    pass.drawIndexed(mesh.indexCount);
    pass.end();
  }

  async function readTestStats() {
    await testReadback.mapAsync(GPUMapMode.READ);
    const pixels = new Uint8Array(testReadback.getMappedRange());
    const background = [CLEAR_COLOUR.r, CLEAR_COLOUR.g, CLEAR_COLOUR.b].map((value) => Math.round(value * 255));
    let nonBackgroundPixels = 0;
    let maxLum = 0;
    for (let pixelY = 0; pixelY < TEST_TARGET_SIZE; pixelY += 1) {
      for (let pixelX = 0; pixelX < TEST_TARGET_SIZE; pixelX += 1) {
        const offset = pixelY * testBytesPerRow + pixelX * 4;
        const red = pixels[offset + (colourFormat.startsWith('bgra') ? 2 : 0)];
        const green = pixels[offset + 1];
        const blue = pixels[offset + (colourFormat.startsWith('bgra') ? 0 : 2)];
        if (Math.max(
          Math.abs(red - background[0]),
          Math.abs(green - background[1]),
          Math.abs(blue - background[2]),
        ) > 3) {
          nonBackgroundPixels += 1;
        }
        maxLum = Math.max(maxLum, (0.2126 * red + 0.7152 * green + 0.0722 * blue) / 255);
      }
    }
    testReadback.unmap();
    return {
      nonBackgroundFrac: nonBackgroundPixels / (TEST_TARGET_SIZE * TEST_TARGET_SIZE),
      maxLum,
    };
  }

  function resizeCanvasTarget() {
    const pixelRatio = Math.min(devicePixelRatio, 2); // legacy desktop cap, inventory §0.
    const width = Math.max(1, Math.round(canvas.clientWidth * pixelRatio));
    const height = Math.max(1, Math.round(canvas.clientHeight * pixelRatio));
    if (width === canvasWidth && height === canvasHeight) return;
    canvasWidth = width;
    canvasHeight = height;
    canvas.width = width;
    canvas.height = height;
    if (canvasDepth) registry.destroy(canvasDepth);
    canvasDepth = makeDepthTexture(registry, 'look-canvas-depth', width, height);
    canvasDepthView = canvasDepth.createView();

import { acquireDevice } from './gpu/device.js';
import { GpuRegistry } from './gpu/registry.js';
import { createLookCamera } from './render/camera.js';
import { createSyntheticDisplayChain } from './render/display-chain.js';
import { loadTwoChartSphereFixture } from './render/fixture-mesh.js';
import { loadGoldLutTexture } from './render/gold-lut-texture.js';
import { createMaterialUniformWriter } from './render/material-uniforms.js';
import { createFixtureMeshRenderer } from './render/renderer.js';
import { SURFACE_PARAM_CONTROLS } from './render/surface-params.js';
import { createSyntheticFieldProvider } from './shared/field-provider.js';
import { createParams } from './shared/params.js';

const canvas = document.querySelector('#lookSurface');
const look = {
  device: null,
  registry: null,
  params: createParams(),
  uncapturedErrors: [],
  renderTestFrame: null,
  scanForNonFinite: null,
  ready: null,
};
window.__v2 = { look };
look.ready = initialize();
window.__v2.ready = look.ready;

async function initialize() {
  const acquisition = await acquireDevice({
    onDeviceLost: ({ reason, message }) => showError(`Device lost (${reason}): ${message}`),
  });
  if (!acquisition.ok) {
    document.querySelector('#status').textContent = 'WebGPU unavailable';
    showError(`${acquisition.stage}: ${acquisition.message}`);
    return look;
  }

  look.device = acquisition.device;
  look.registry = new GpuRegistry(look.device);
  look.device.addEventListener('uncapturederror', (event) => {
    event.preventDefault();
    const message = event.error?.message || 'Unknown WebGPU error';
    look.uncapturedErrors.push(message);
    showError(message);
  });
  const reportCompilationMessage = (message) => {
    if (message.type === 'error') showError(`[${message.shader}] ${message.message}`);
    else console.warn(`[${message.shader}] ${message.message}`);
  };

  const fieldProvider = createSyntheticFieldProvider(look.device, look.registry, { size: 256 });
  const [mesh, goldLut] = await Promise.all([
    loadTwoChartSphereFixture({ device: look.device, registry: look.registry }),
    loadGoldLutTexture({ device: look.device, registry: look.registry }),
  ]);
  const displayChain = await createSyntheticDisplayChain({
    device: look.device,
    registry: look.registry,
    fieldProvider,
    onCompilationMessage: reportCompilationMessage,
  });
  const cameraRig = createLookCamera({ device: look.device, registry: look.registry, canvas });
  const materialUniforms = createMaterialUniformWriter({
    device: look.device,
    registry: look.registry,
    fieldSize: fieldProvider.size,
    lut: goldLut,
  });
  materialUniforms.write(look.params);
  const renderer = await createFixtureMeshRenderer({
    device: look.device,
    registry: look.registry,
    canvas,
    cameraRig,
    materialUniforms,
    mesh,
    displayChain,
    goldLut,
    onCompilationMessage: reportCompilationMessage,
  });

  installSurfaceControls(materialUniforms);
  look.renderTestFrame = async () => {
    fieldProvider.frame({ timeMs: 0, force: true });
    const encoder = look.device.createCommandEncoder({ label: 'look-test-frame-encoder' });
    displayChain.encode(encoder, look.params);
    renderer.encodeTestFrame(encoder, look.params);
    look.device.queue.submit([encoder.finish()]);
    return renderer.readTestStats();
  };
  look.scanForNonFinite = () => displayChain.scanForNonFinite();
  document.querySelector('#status').textContent = `${mesh.name} · ${displayChain.displayFormat} display · orbit enabled`;
  startAnimation({ fieldProvider, displayChain, renderer });
  return look;
}

function startAnimation({ fieldProvider, displayChain, renderer }) {
  const frame = (timeMs) => {
    fieldProvider.frame({ timeMs });
    const encoder = look.device.createCommandEncoder({ label: 'look-frame-encoder' });
    displayChain.encode(encoder, look.params);
    renderer.encodeCanvas(encoder, look.params);
    look.device.queue.submit([encoder.finish()]);
    requestAnimationFrame(frame);
  };
  requestAnimationFrame(frame);
}

function installSurfaceControls(materialUniforms) {
  const controls = document.querySelector('#controls');
  for (const description of SURFACE_PARAM_CONTROLS) {
    const { parameterName, parameter } = description;
    const label = document.createElement('label');
    const copy = document.createElement('span');
    const title = document.createElement('span');
    const help = document.createElement('span');
    const input = document.createElement('input');
    const output = document.createElement('output');
    copy.className = 'copy';
    title.textContent = description.label;
    help.className = 'help';
    help.tabIndex = 0;
    help.textContent = '?';
    help.title = description.help;
    copy.append(title, help);
    input.id = `look-${parameterName}`;

    if (parameter.type === 'number') {
      label.className = 'number-control';
      input.type = 'range';
      Object.assign(input, { min: parameter.min, max: parameter.max, step: parameter.step });
      input.value = look.params[parameterName];
      output.value = formatNumber(look.params[parameterName], parameter.step);
      input.addEventListener('input', () => {
        look.params[parameterName] = Number(input.value);
        output.value = formatNumber(look.params[parameterName], parameter.step);
        materialUniforms.write(look.params);
      });
      label.append(copy, input, output);
    } else if (parameter.type === 'boolean') {
      label.className = 'toggle-control';
      input.type = 'checkbox';
      input.checked = look.params[parameterName];
      input.addEventListener('input', () => {
        look.params[parameterName] = input.checked;
        materialUniforms.write(look.params);
      });
      label.append(copy, input);
    } else if (parameter.type === 'color') {
      label.className = 'colour-control';
      input.type = 'color';
      input.value = look.params[parameterName];
      input.addEventListener('input', () => {
        look.params[parameterName] = input.value;
        materialUniforms.write(look.params);
      });
      label.append(copy, input);
    }
    controls.append(label);
  }
