const TWO_CHART_SPHERE_URL = new URL('../../tests/fixtures/two-chart-sphere.json', import.meta.url);

export async function loadTwoChartSphereFixture({ device, registry, fetchImpl = fetch }) {
  const response = await fetchImpl(TWO_CHART_SPHERE_URL);
  if (!response.ok) throw new Error(`Fixture request failed with HTTP ${response.status}`);
  const fixture = await response.json();
  assertFixture(fixture);

  const positions = fixture.attributes.positions;
  const uv = fixture.attributes.uv;
  const vertexCount = positions.length / 3;
  const interleaved = new Float32Array(vertexCount * 8);
  for (let vertexIndex = 0; vertexIndex < vertexCount; vertexIndex += 1) {
    const positionOffset = vertexIndex * 3;
    const vertexOffset = vertexIndex * 8;
    const worldX = positions[positionOffset];
    const worldY = positions[positionOffset + 1];
    const worldZ = positions[positionOffset + 2];
    const normalLength = Math.hypot(worldX, worldY, worldZ) || 1;
    interleaved.set([
      worldX, worldY, worldZ,
      worldX / normalLength, worldY / normalLength, worldZ / normalLength,
      uv[vertexIndex * 2], uv[vertexIndex * 2 + 1],
    ], vertexOffset);
  }

  const maximumIndex = fixture.indices.reduce((maximum, index) => Math.max(maximum, index), 0);
  const IndexArray = maximumIndex <= 0xffff ? Uint16Array : Uint32Array;
  const indices = new IndexArray(fixture.indices);
  const vertexBuffer = uploadBuffer(registry, {
    label: 'look-two-chart-sphere-vertices',
    values: interleaved,
    usage: GPUBufferUsage.VERTEX,
  });
  const indexBuffer = uploadBuffer(registry, {
    label: 'look-two-chart-sphere-indices',
    values: indices,
    usage: GPUBufferUsage.INDEX,
  });

  return Object.freeze({
    name: fixture.name,
    vertexBuffer,
    indexBuffer,
    indexCount: indices.length,
    indexFormat: indices instanceof Uint16Array ? 'uint16' : 'uint32',
  });
}

function uploadBuffer(registry, { label, values, usage }) {
  const buffer = registry.createBuffer({
    label,
    size: values.byteLength,
    usage,
    mappedAtCreation: true,
  });
  new values.constructor(buffer.getMappedRange()).set(values);
  buffer.unmap();
  return buffer;
}

function assertFixture(fixture) {
  const positions = fixture?.attributes?.positions;
  const uv = fixture?.attributes?.uv;
  if (fixture?.name !== 'two-chart-sphere'
      || !Array.isArray(positions)
      || !Array.isArray(uv)
      || !Array.isArray(fixture.indices)
      || positions.length % 3 !== 0
      || uv.length / 2 !== positions.length / 3) {
    throw new Error('two-chart-sphere fixture has an invalid mesh contract');
  }
}

import { Matrix4, PerspectiveCamera } from '../../vendor/three.module.js';
import { OrbitControls } from '../../vendor/controls/OrbitControls.js';

export const LOOK_CAMERA_CONSTANTS = Object.freeze({
  fovDegrees: 42.8571,
  nearWorld: 0.04,
  farWorld: 1200,
  initialWorldPosition: Object.freeze([1.893468, 5.498426, -5.633916]),
  targetWorldPosition: Object.freeze([0, 0, 0]),
  dampingFactor: 0.07,
  rotateSpeed: 0.65,
  zoomSpeed: 0.7,
  minDistanceWorld: 3.2,
  maxDistanceWorld: 22.4,
  maxPolarAngleRadians: Math.PI / 2 - 0.04,
});

export function createLookCamera({ device, registry, canvas }) {
  const constants = LOOK_CAMERA_CONSTANTS;
  const camera = new PerspectiveCamera(
    constants.fovDegrees,
    Math.max(canvas.clientWidth, 1) / Math.max(canvas.clientHeight, 1),
    constants.nearWorld,
    constants.farWorld,
  );
  camera.position.set(...constants.initialWorldPosition);
  camera.lookAt(...constants.targetWorldPosition);
  camera.updateMatrixWorld(true);

  const controls = new OrbitControls(camera, canvas);
  controls.enablePan = false;
  controls.enableDamping = true;
  controls.dampingFactor = constants.dampingFactor;
  controls.rotateSpeed = constants.rotateSpeed;
  controls.zoomSpeed = constants.zoomSpeed;
  controls.minDistance = constants.minDistanceWorld;
  controls.maxDistance = constants.maxDistanceWorld;
  controls.minPolarAngle = 0;
  controls.maxPolarAngle = constants.maxPolarAngleRadians;
  controls.target.set(...constants.targetWorldPosition);
  controls.update();

  const uniformBuffer = registry.createBuffer({
    label: 'look-camera-uniforms',
    size: 80,
    usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
  });
  const uniformValues = new Float32Array(20);
  const viewProjection = new Matrix4();
  let lastAspect = camera.aspect;

  function update(width, height) {
    const aspect = Math.max(width, 1) / Math.max(height, 1);
    if (aspect !== lastAspect) {
      lastAspect = aspect;
      camera.aspect = aspect;
      camera.updateProjectionMatrix();
    }
    controls.update();
    camera.updateMatrixWorld(true);
    viewProjection.multiplyMatrices(camera.projectionMatrix, camera.matrixWorldInverse);
    uniformValues.set(viewProjection.elements, 0);
    uniformValues[16] = camera.position.x;
    uniformValues[17] = camera.position.y;
    uniformValues[18] = camera.position.z;
    uniformValues[19] = 1;
    device.queue.writeBuffer(uniformBuffer, 0, uniformValues);
  }

  update(canvas.clientWidth, canvas.clientHeight);
  return { camera, controls, uniformBuffer, update, dispose: () => controls.dispose() };
}

/**
 * Renderer contract for a scalar field. Providers own their texture and view; frame()
 * advances content without changing either identity.
 */
export function assertFieldProvider(provider) {
  if (!provider?.texture || !provider?.view || !Number.isInteger(provider.size) || provider.size <= 0) {
    throw new TypeError('A field provider requires texture, view, and a positive integer size');
  }
  if (typeof provider.frame !== 'function') throw new TypeError('A field provider requires frame()');
  return provider;
}

export function createSyntheticFieldProvider(device, registry, {
  size = 512,
  label = 'synthetic-look-field',
} = {}) {
  if (!device?.queue) throw new TypeError('A GPUDevice is required');
  if (!registry?.createTexture) throw new TypeError('A GPU registry is required');

  const texture = registry.createTexture({
    label,
    size: [size, size, 1],
    format: 'r32float',
    usage: GPUTextureUsage.COPY_DST | GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.STORAGE_BINDING,
  });
  const view = texture.createView({ label: `${label}-view` });
  const floatsPerRow = Math.ceil((size * 4) / 256) * 64;
  const upload = new Float32Array(floatsPerRow * size);
  let lastPaintedPhase = Number.NaN;

  function frame({ timeMs = 0, force = false } = {}) {
    const paintedPhase = Math.floor(timeMs / 250) / 16;
    if (!force && paintedPhase === lastPaintedPhase) return;
    paintSyntheticField(upload, size, floatsPerRow, paintedPhase);
    device.queue.writeTexture(
      { texture },
      upload,
      { bytesPerRow: floatsPerRow * 4, rowsPerImage: size },
      [size, size, 1],
    );
    lastPaintedPhase = paintedPhase;
  }

  const provider = {
    texture,
    view,
    size,
    frame,
    destroy() {
      registry.destroy(texture);
    },
  };
  frame({ force: true });
  return assertFieldProvider(provider);
}

export function syntheticFieldValue(uvX, uvY, phase = 0) {
  const wave = 0.5 + 0.5 * Math.sin((uvX * 5.1 + uvY * 2.7 + phase) * Math.PI * 2);
  const ringDistance = Math.abs(Math.hypot(uvX - 0.34, uvY - 0.48) - 0.22);
  const ring = 1 - smoothstep(0.018, 0.06, ringDistance);
  const paintedFront = smoothstep(-0.05, 0.05, uvX - 0.64 + 0.08 * Math.sin(uvY * 14 + phase));
  const noise = hash2d(Math.floor(uvX * 257), Math.floor(uvY * 257));
  return Math.min(1, Math.max(0, 0.06 + wave * 0.19 + ring * 0.58 + paintedFront * 0.42 + noise * 0.08));
}

function paintSyntheticField(target, size, floatsPerRow, phase) {
  for (let texelY = 0; texelY < size; texelY += 1) {
    for (let texelX = 0; texelX < size; texelX += 1) {
      target[texelY * floatsPerRow + texelX] = syntheticFieldValue(
        (texelX + 0.5) / size,
        (texelY + 0.5) / size,
        phase,
      );
    }
  }
}

function smoothstep(low, high, value) {
  const t = Math.min(1, Math.max(0, (value - low) / (high - low)));
  return t * t * (3 - 2 * t);
}

function hash2d(x, y) {
  let value = Math.imul(x ^ 0x9e3779b9, 0x85ebca6b) ^ Math.imul(y, 0xc2b2ae35);
  value ^= value >>> 16;
  return (value >>> 0) / 0xffffffff;
}

