  const header = bytes.slice(0, GOLD_LUT_FORMAT.headerBytes);
  const crcOffset = GOLD_LUT_FORMAT.offsets.headerCrc32;
  header.fill(0, crcOffset, crcOffset + 4);
  return crc32(header);
