function assertMagic(bytes) {
  for (let index = 0; index < GOLD_LUT_FORMAT.magic.length; index += 1) {
    if (bytes[index] !== GOLD_LUT_FORMAT.magic.charCodeAt(index)) {
      throw new Error('gold LUT magic is invalid');
